            savdhani = "अहंकार और घमंड से दूर रहें। दोस्तों व भाइयों के साथ छल न करें।"; //[span_187](start_span)[span_187](end_span)
          } else if (house == 8) {
            shlok = "मरे बच्चे इतने-कब्र भर रही है\nगिला मर चुकों का-तू क्या कर रही है\nमारग घर जब केतु बैठा\nमर्द औरत न सुखिया जोड़ा"; //[span_188](start_span)[span_188](end_span)
            detailFalit = "संतान के कष्ट में छत पर रोने वाला कुत्ता। यमदूतों की आहट पहचानने वाला—आने वाली अनहोनी का पूर्वाभास हो जाता है। पेशाब या पैरों से जुड़ी समस्या हो सकती है।"; //[span_189](start_span)[span_189](end_span)
            conditions = "यदि मंगल खाना नं. 12 में हो तो कष्ट समाप्त हो जाते हैं। गुरु 2 में हो तो पुत्र लाभ होता है।"; //[span_190](start_span)[span_190](end_span)
            upaay = "काला-सफेद कंबल किसी धर्मस्थान में दान दें। कान छिदवाएं और सोने का तार डालें।"; //[span_191](start_span)[span_191](end_span)
            savdhani = "घर के सामने या छत पर कुत्ते को रोने न दें।"; //[span_192](start_span)[span_192](end_span)
          } else {
            shlok = "केतु खाना नं. $house का फल";
            detailFalit = "पुत्र संतान, मामा कुल और पैरों-जोड़ों की स्थिति खाना नं. $house के अधीन रहती है।"; //[span_193](start_span)[span_193](end_span)
            conditions = "गुरु के नियमों का पालन करने से केतु सदैव अमृत तुल्य फल देता है।";
            upaay = "कुत्तों को मीठी या फीकी रोटियां खिलाएं।"; //[span_194](start_span)[span_194](end_span)
            savdhani = "बुजुर्गों का दिल न दुखाएं।";
          }
          break;
      }

      reports.add({
        "planet": planet,
        "house": house.toString(),
        "shlok": shlok,
        "detailFalit": detailFalit,
        "conditions": conditions,
        "upaay": upaay,
        "savdhani": savdhani,
      });
    });

    return {"reports": reports};
  }

  static Map<String, int> calculateVarshphal(Map<String, int> birthChart, int age) {
    Map<String, int> vChart = {};
    birthChart.forEach((planet, house) {
      int newHouse = ((house - 1 + (age % 12)) % 12) + 1;
      vChart[planet] = newHouse;
    });
    return vChart;
  }
}
